node -e "
const fs = require('fs');
const path = require('path');
const dir = 'node_modules/@re-cinq/eslint-plugin-re-lint';
function walk(d) {
  for (const e of fs.readdirSync(d, {withFileTypes: true})) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p);
    else console.log(p);
  }
}
walk(dir);
"

